"""One investigator lineage with separate physical and native virtual campaigns.

The companion stores virtual specimens and returns. Its model references resolve
to the physical campaign's authoritative model ledger, never to a second agent.
Simulation files enter the existing computational-artifact path, not physical
evidence. Simulator configuration and native execution remain owner-side.
"""

from __future__ import annotations

import copy
import hashlib
import json
from pathlib import Path
from types import SimpleNamespace

from ..contracts import ConflictError, request_record
from ..operator import Campaign
from .controller import (
    REQUEST,
    STRING,
    Investigator,
    ScientificExecutionError,
    _spec,
    encoded,
    signature,
)
from .executor import execute
from .feedback import forecast_issues, public_diagnostics, request_preview
from .vision_tools import VISION_TOOLS, VisionInvestigator

REQUEST_SIMULATION = _spec(
    "request_simulation",
    "Propose and execute a conditional virtual instrument request in the companion synthetic "
    "campaign. Uses the same request structure as submit_batch, with origin synthetic and "
    "separate virtual specimen/preparation/cycle identities. Manufacture creates virtual bodies; "
    "measure and anneal use their released virtual histories. An active model freezes its "
    "prediction first; without a model the record explicitly abstains. The native simulator is "
    "fixed and independent of your model edits. Returned hashes are readable with read_artifact, "
    "compute artifact_sha256s and adopt_model artifact_sha256s. These conditional computational "
    "returns never become physical measurements or consume physical material. Simulation use "
    "is optional; simulation=magnetic selects the separately named historical magnetic laboratory; "
    "omitting simulation preserves the legacy laboratory. Inspect virtual_laboratories for supported contracts and assumptions.",
    {"request_id": STRING, "request": copy.deepcopy(REQUEST), "rationale": STRING, "simulation": STRING},
    ("request_id", "request"),
)
REQUEST_SIMULATION["parameters"]["properties"]["request"]["description"] = (
    "Virtual request using a separate synthetic lot, specimen, preparation and cycle identity."
)
REQUEST_SIMULATION["parameters"]["properties"]["request"]["properties"].update(
    operation={"type": "string", "enum": ["manufacture", "measure", "anneal"]},
    input_stage=STRING, output_stage=STRING,
)
HYBRID_TOOLS = [*VISION_TOOLS, REQUEST_SIMULATION]
NO_MODEL = "unmodeled-exploration-abstention"
NO_MODEL_SOURCE = "# No investigator model was adopted; all virtual predictions abstain.\n"


class _CompanionCampaign(Campaign):
    """Resolve model references to one authoritative ledger, without copying it."""

    def models(self):
        return self.investigator_campaign.models()

    def model(self, model_id):
        if model_id == NO_MODEL:
            return {"model_id": NO_MODEL,
                    "source_sha256": hashlib.sha256(NO_MODEL_SOURCE.encode()).hexdigest()}
        return self.investigator_campaign.model(model_id)


def _artifact_names(inv):
    names = {}
    try:
        for release in inv.campaign.store.all("release"):
            delivery = inv.campaign.store.get("delivery", release["delivery_id"])
            for fname, blob in delivery["raw_files"].items():
                names.setdefault(blob["sha256"], {"name": fname, "delivery_id": release["delivery_id"]})
    except Exception:
        pass
    try:
        for row in inv._computation_artifacts():
            names.setdefault(row["sha256"], {"name": row.get("name") or row.get("path"), "execution_id": row.get("execution_id")})
    except Exception:
        pass
    return names


def _with_request_echo(inv, name, arguments, result):
    if not isinstance(result, dict) or "request_echo" in result or not isinstance(arguments, dict):
        return result
    names = _artifact_names(inv)
    ident = lambda h: {"sha256": h, **names.get(h, {"name": None})}
    echo = {"tool": name, "note": "This return answers the call named here."}
    if name in ("read_artifact", "view_image") and isinstance(arguments.get("sha256"), str):
        echo["artifact"] = ident(arguments["sha256"])
        if "offset" in arguments:
            echo["offset"] = arguments["offset"]
    elif name == "compute":
        echo["mounted"] = [ident(h) for h in arguments.get("artifact_sha256s") or []]
        first = next((line.strip() for line in str(arguments.get("code", "")).splitlines() if line.strip()), "")
        echo["code_first_line"] = first[:160]
    elif name == "record_decision":
        echo["decision"] = arguments.get("decision")
        echo["note"] = "This return is the decision record you submitted in this call, as stored."
    elif name in ("inspect_state", "read_sources", "read_evidence", "read_model"):
        echo.update({k: arguments[k] for k in ("section", "key", "offset", "source_sha256") if k in arguments})
    elif name in ("request_simulation", "preview_request", "submit_batch"):
        echo["request_id"] = arguments.get("request_id")
    elif name in ("stage_model", "adopt_model"):
        echo.update({k: arguments[k] for k in ("source_sha256",) if k in arguments})
    return {"request_echo": echo, **result}


class HybridInvestigator(VisionInvestigator):
    def __init__(self, campaign, directory, *, executor=execute, sources=None):
        super().__init__(campaign, directory, executor=executor, sources=sources)
        self.simulation_root = campaign.store.path.parent / "simulation"
        try:
            self.owner_simulation = json.loads(
                (self.simulation_root / "owner_simulation_runtime.json").read_text())
            # Opening an established companion does not create or migrate a runtime.
            self.simulation = _CompanionCampaign.open(self.simulation_root / "campaign")
            self.simulation.investigator_campaign = campaign
            if self.simulation.config.get("execution_mode") != "synthetic":
                raise ValueError("hybrid companion must be initialized as a synthetic campaign")
            from .virtual_lab import open_companion
            self.magnetic = open_companion(self)
        except BaseException:
            super().close()
            raise

    def close(self):
        if getattr(self, "magnetic", None) is not None:
            self.magnetic.simulation.close()
        self.simulation.close()
        super().close()

    def _source_artifacts(self):
        return [{**record, "evidence_class": "source_reference_artifact",
                 "execution_id": "source-reference", "receipt_relative_path": record["name"]}
                for record in self.sources.get("task", {}).get("source_artifacts", [])]

    def _simulation_artifacts(self):
        return [{**artifact, "evidence_class": "conditional_computational",
                 "origin": "synthetic", "physical_execution": False,
                 "execution_id": "simulation-" + artifact["delivery_id"],
                 "receipt_relative_path": "blobs/" + artifact["sha256"]}
                for artifact in self.simulation.artifacts()] + (self.magnetic.artifacts() if getattr(self, "magnetic", None) else [])

    def _computation_artifacts(self):
        # Reuse selection, adoption and exact-hash forecast mounting unchanged.
        return [*super()._computation_artifacts(), *self._simulation_artifacts(),
                *self._source_artifacts()]

    def _artifact_binding(self, digest):
        self._artifact_digest(digest)
        artifact = next((row for row in self._simulation_artifacts()
                         if row["sha256"] == digest), None)
        if artifact is not None:
            store = self.magnetic.simulation.store if artifact.get("simulation") == "magnetic" else self.simulation.store
            return store.blobs, (digest,), artifact
        artifact = next((row for row in self._source_artifacts()
                         if row["sha256"] == digest), None)
        if artifact is not None:
            path = Path(self.owner_simulation["source_artifact_paths"][digest])
            return path.parent, (path.name,), artifact
        return super()._artifact_binding(digest)

    def _simulation_state(self, *, summary=False):
        state = self.simulation.state()
        artifacts = [r for r in self._simulation_artifacts() if r.get("simulation") != "magnetic"]
        common = {"campaign_id": state["campaign_id"],
                  "evidence_class": "conditional_computational", "origin": "synthetic",
                  "physical_execution": False, "resources": state["resources"],
                  "shared_investigator_model_id": self.campaign.state()["active_model_id"]}
        if summary:
            return {**common, "request_count": len(state["requests"]),
                    "evidence_count": len(state["evidence"]),
                    "recent_requests": [{key: row.get(key) for key in
                        ("request_id", "status", "model_id", "released_delivery_ids")}
                        for row in state["requests"][-5:]],
                    "artifact_count": len(artifacts), "recent_artifacts": artifacts[-5:],
                    "retrieval": "inspect_state(section='simulation') for virtual evidence, histories and artifacts"}
        return {**state, **common, "artifacts": artifacts}

    def state(self, *, summary=False):
        state = super().state(summary=summary)
        state["simulation"] = self._simulation_state(summary=summary)
        if getattr(self, "magnetic", None):
            state["simulation_magnetic"] = self.magnetic.public_state(summary=summary)
        state["virtual_laboratories"] = {"legacy": {"selection": "omit simulation or use legacy", "state_section": "simulation"},
            **({"magnetic": self.magnetic.owner_simulation["public_capabilities"]} if getattr(self, "magnetic", None) else {})}
        from .virtual_lab import executable_contracts
        state["executable_contracts"] = executable_contracts()
        if summary:
            state["source_artifact_count"] = len(self._source_artifacts())
            state["sections"].extend(["simulation", "source_artifacts", "virtual_laboratories", "executable_contracts"])
            if getattr(self, "magnetic", None):
                state["sections"].append("simulation_magnetic")
        else:
            state["source_artifacts"] = self._source_artifacts()
        return state

    def _payload(self, request=None, inputs=None):
        payload = super()._payload(request=request, inputs=inputs)
        payload["investigation_state"]["simulation"] = self._simulation_state()
        if getattr(self, "magnetic", None):
            payload["investigation_state"]["simulation_magnetic"] = self.magnetic.public_state()
        # payload.evidence remains exclusively the physical campaign's evidence.
        return payload

    def feedback_summary(self):
        physical = super().feedback_summary()
        if not self.feedback_enabled:
            return physical
        # Reuse the existing compact reducer with the companion's released state.
        # This does not swap the investigator campaign or mix evidence cutoffs.
        virtual = Investigator.feedback_summary(SimpleNamespace(
            feedback_enabled=True, campaign=self.simulation))
        virtual.update(origin="synthetic", evidence_class="conditional_computational",
                       physical_execution=False)
        for row in virtual["recent_released_requests"]:
            row.update(origin="synthetic", evidence_class="conditional_computational",
                       retrieval="inspect_feedback(request_id='simulation:" + row["request_id"] + "')")
        return {**physical, "simulation": virtual,
                **({"magnetic": self.magnetic.public_feedback()} if getattr(self, "magnetic", None) else {})}

    def _apply(self, call_id, name, args, intent):
        if name == "inspect_feedback" and "request_id" in args:
            request_id = args["request_id"]
            if request_id.startswith("magnetic:"):
                if not getattr(self, "magnetic", None):
                    raise ValueError("named magnetic companion is not configured")
                return self._page(self.magnetic.diagnostics(request_id.removeprefix("magnetic:")), args)
            explicit_virtual = request_id.startswith("simulation:")
            virtual_id = request_id.removeprefix("simulation:") if explicit_virtual else request_id
            if explicit_virtual or (self.simulation.store.has("request", virtual_id)
                                    and not self.campaign.store.has("request", request_id)):
                report = public_diagnostics(self.simulation.request(virtual_id), self.simulation.evidence())
                report.update(origin="synthetic", evidence_class="conditional_computational",
                              physical_execution=False, campaign_id=self.simulation.config["campaign_id"])
                return self._page(report, args)
        return super()._apply(call_id, name, args, intent)

    def _virtual_request(self, proposed):
        request = request_record(proposed)
        if request["origin"] != "synthetic":
            raise ValueError("request_simulation requires origin synthetic")
        if request.get("operation", "manufacture") != "manufacture":
            for specimen in request["specimens"]:
                history = self.simulation.specimen_history(specimen["specimen_id"])
                specimen.setdefault("prior_processing_conditions", history["processing_history_conditions"])
                if history["remaining_mass_g"] is not None:
                    specimen.setdefault("remaining_mass_g", history["remaining_mass_g"])
                    specimen["conditions"].setdefault("mass_g", history["remaining_mass_g"])
        # Existing provider control validation, not a new scientific admission rule.
        if self.owner_simulation["world_config"].get("family") == "rpi_conditional_workflow_v1":
            from ..models.workflow_response import validate_workflow_request_controls
            validate_workflow_request_controls(request)
        return request

    def _prepare_simulation(self, args):
        request = self._virtual_request(args["request"])
        active = self.campaign.state()["active_model_id"]
        if active:
            model = self.campaign.model(active)
            artifacts = self._selected_artifacts(model.get("artifact_sha256s", []))
            forecast = self._forecast(model["source"], request, artifacts)
        else:
            reason = args.get("rationale") or "No investigator model adopted; exploratory virtual request with no prediction."
            forecast = {"forecast": {"predictions": [
                {"specimen_id": specimen["specimen_id"], **{
                    name: {"mean": None, "sd": None, "unit": unit,
                           "status": "abstained", "reason": reason}
                    for name, unit in (("density_g_cm3", "g/cm^3"), ("grain_size_nm", "nm"))}}
                for specimen in request["specimens"]]},
                "evidence_ids": [row["evidence_id"] for row in self.campaign.evidence()],
                "input_sha256": signature(self._payload(request=request)), "executions": []}
        return {"request": request, "model_id": active or NO_MODEL, **forecast,
                "simulation_evidence_ids": [row["evidence_id"] for row in self.simulation.evidence()]}

    def _preview(self, args):
        from .virtual_lab import select_companion
        selected = select_companion(self, args)
        if selected is not self:
            return selected._preview(args)
        if args["request"].get("origin") != "synthetic":
            return super()._preview(args)
        request = json.loads(encoded(args["request"]))
        result = request_preview(request, self.simulation.state(), self.sources)
        result.update(status="read_only_preview", campaign_mutated=False, experiment_executed=False,
                      provisional_prediction=True, evidence_class="conditional_computational",
                      inference_resources=self.inference_resources())
        prediction = args.get("prediction")
        if prediction is not None and "source_sha256" in args:
            result["errors"].append("provide prediction or source_sha256, not both")
        elif prediction is None and not result["errors"]:
            request = self._virtual_request(request)
            active = self.campaign.state()["active_model_id"]
            model = self.campaign.model(active) if active else None
            source = (self._model_source(args["source_sha256"]) if "source_sha256" in args
                      else model["source"] if model else None)
            if source is not None:
                artifacts = model.get("artifact_sha256s", []) if model and model["source"] == source else []
                try:
                    forecast = self._forecast(source, request, artifacts)
                    prediction = forecast["forecast"]
                    result.update(calculation_receipts=forecast["executions"],
                                  source_sha256=hashlib.sha256(source.encode()).hexdigest(),
                                  input_sha256=forecast["input_sha256"])
                except ScientificExecutionError as error:
                    result["errors"].append("model calculation failed; this is not experimental evidence")
                    result["calculation_error"] = error.public_details
            else:
                result["notes"].append("No active model; request_simulation can proceed with an explicit abstention")
        if prediction is not None:
            checks = forecast_issues(prediction, request)
            result.update(prediction=prediction, forecast_targets=checks["targets"])
            result["errors"].extend(checks["errors"])
            result["notes"].extend(checks["notes"])
        result["contract_ready"] = not result["errors"]
        result["limits"] = ["Virtual preview is provisional and does not establish physical applicability"]
        return result

    def _apply_simulation(self, call_id, args, intent):
        from ..workflow import fulfill_simulation

        rid = args["request_id"]
        if not self.simulation.store.has("request", rid):
            active = self.campaign.state()["active_model_id"] or NO_MODEL
            if active != intent["model_id"]:
                raise ConflictError("active model changed after virtual prediction")
            if set(intent["evidence_ids"]) != {row["evidence_id"] for row in self.campaign.evidence()}:
                raise ConflictError("physical evidence changed after virtual prediction")
            self.simulation.store.set_meta("active_model_id", intent["model_id"])
        committed = self.simulation.submit(
            intent["request"], intent["forecast"], rid, call_id="virtual:" + call_id,
            expected_model_id=intent["model_id"],
            expected_evidence_ids=intent["simulation_evidence_ids"])
        # Native fulfillment is idempotent for a received delivery. Existing
        # failures remain inspectable; a restart cannot silently rerun a failure.
        pending = next(row for row in self.simulation.state()["requests"] if row["request_id"] == rid)
        if pending["active_execution_failure"]:
            return {"status": "execution_failed", "request_id": rid,
                    "scientific_negative": False, "physical_execution": False,
                    "evidence_class": "conditional_computational",
                    "failure": pending["active_execution_failure"]}
        result = fulfill_simulation(
            self.simulation.store.path, rid,
            runtime=Path(self.owner_simulation["runtime"]),
            artifact_directory=self.simulation_root / "executions" / hashlib.sha256(rid.encode()).hexdigest()[:24],
            world_config=self.owner_simulation["world_config"], seed=self.owner_simulation["seed"])
        delivery_id = result.get("delivery_id")
        if delivery_id:
            self.simulation.release(delivery_id, "native-conditional-simulation",
                                    call_id="virtual-release:" + delivery_id)
        return {"status": "complete" if delivery_id else "execution_failed",
                "request_id": rid, "delivery_id": delivery_id,
                "model_id": committed["model_id"], "prediction": committed["prediction"],
                "evidence_class": "conditional_computational", "origin": "synthetic",
                "physical_execution": False, "scientific_negative": False,
                "artifacts": [row for row in self._simulation_artifacts()
                              if row["delivery_id"] == delivery_id],
                "retrieval": "inspect_state(section='simulation'); read_artifact and compute/adopt_model artifact_sha256s bind these exact outputs"}

    def call(self, call_id, name, arguments):
        # Echo the request identity in every
        # tool result so the investigator can match each return to its own call. Added after the
        # durable result is stored; stored results and replays are unchanged.
        result = self._call_untagged(call_id, name, arguments)
        return _with_request_echo(self, name, arguments, result)

    def _call_untagged(self, call_id, name, arguments):
        if name != "request_simulation":
            return super().call(call_id, name, arguments)
        from .virtual_lab import select_companion
        selected = select_companion(self, arguments)
        if selected is not self:
            return HybridInvestigator.call(selected, call_id, name, arguments)
        if not isinstance(call_id, str) or not call_id or len(call_id) > 256:
            raise ValueError("bounded nonempty call_id required")
        parameters = REQUEST_SIMULATION["parameters"]
        if not isinstance(arguments, dict) or set(arguments) - set(parameters["properties"]):
            raise ValueError("unexpected tool arguments")
        if not set(parameters["required"]).issubset(arguments):
            raise ValueError("missing required arguments")
        key = signature({"name": name, "arguments": arguments})
        previous = self.db.execute("SELECT * FROM calls WHERE id=?", (call_id,)).fetchone()
        if previous and previous["signature"] != key:
            raise ValueError("call ID reused with changed arguments")
        if previous and previous["result"]:
            return json.loads(previous["result"])
        if previous is None:
            self.db.execute("INSERT INTO calls VALUES(?,?,?,?,NULL,NULL)", (call_id, key, name, encoded(arguments)))
        intent = json.loads(previous["intent"]) if previous and previous["intent"] else None
        if intent is None:
            intent = self._prepare_simulation(arguments)
            self.db.execute("UPDATE calls SET intent=? WHERE id=?", (encoded(intent), call_id))
        result = self._apply_simulation(call_id, arguments, intent)
        self.db.execute("UPDATE calls SET result=? WHERE id=?", (encoded(result), call_id))
        return result
